import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const AMOUNT_RE = /^-?\d+(\.\d{1,2})?$/;
const ID_RE = /^\d+$/;
// 가정: 등록 시 상태는 '신청'으로 시작한다 (BEHAVIOR.md 값의 출처)
const INITIAL_STATUS = '신청';
// 가정: 결산 확정·마감 시 결재 필요 여부는 미정이므로 이 기능은 마감 상태의 자료만 수정·삭제를 막는다
const CLOSED_STATUS = '마감';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

const SELECT_COLUMNS = `
  closing_entry_id AS "closingEntryId",
  account_item_id AS "accountItemId",
  period_start AS "periodStart",
  period_end AS "periodEnd",
  accounting_unit AS "accountingUnit",
  closing_amount AS "closingAmount",
  memo AS "memo",
  status AS "status"
`;

function invalid(message: string): ApiError {
  return new ApiError(422, 'INVALID_CLOSING_ENTRY', message);
}

function text(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function amountText(value: unknown): string | null {
  let s = '';
  if (typeof value === 'number' && Number.isFinite(value)) {
    s = String(value);
  } else if (typeof value === 'string') {
    s = value.trim();
  } else {
    return null;
  }
  return AMOUNT_RE.test(s) ? s : null;
}

function idOf(value: unknown): string | null {
  const s = typeof value === 'number' ? String(value) : text(value);
  return ID_RE.test(s) ? s : null;
}

function memoOf(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > 500) {
    throw invalid('적요는 500자 이하의 글자여야 합니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr01001Controller {
  @Get('/closing-entries')
  async listClosingEntries(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const periodStart = text(q.periodStart);
    const periodEnd = text(q.periodEnd);
    const accountingUnit = text(q.accountingUnit);
    if (!DATE_RE.test(periodStart) || !DATE_RE.test(periodEnd)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결산 기간 시작일과 종료일을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    if (accountingUnit.length > 50) {
      throw new ApiError(400, 'VALIDATION_FAILED', '회계단위는 50자 이하여야 합니다.');
    }
    const pageNo = q.page === undefined || q.page === '' ? 0 : Number(q.page);
    const sizeNo = q.size === undefined || q.size === '' ? DEFAULT_SIZE : Number(q.size);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(sizeNo) || sizeNo < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 쪽 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeNo, MAX_SIZE);
    return transaction(async (db) => {
      const params = {
        periodStart,
        periodEnd,
        accountingUnit,
        limit: size,
        offset: pageNo * size,
      };
      const where = `
        period_start >= CAST(:periodStart AS date)
        AND period_end <= CAST(:periodEnd AS date)
        AND (:accountingUnit = '' OR accounting_unit = :accountingUnit)
      `;
      const items = await db.query(
        `SELECT ${SELECT_COLUMNS} FROM closing_entry WHERE ${where}
         ORDER BY period_start DESC, closing_entry_id DESC
         LIMIT :limit OFFSET :offset`,
        params,
      );
      const counted = await db.query(
        `SELECT COUNT(*) AS "total" FROM closing_entry WHERE ${where}`,
        params,
      );
      return { items, page: pageNo, size, total: Number(counted[0].total) };
    });
  }

  @Post('/closing-entries')
  @HttpCode(200)
  async createClosingEntry(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const periodStart = text(data.periodStart);
    const periodEnd = text(data.periodEnd);
    const accountingUnit = text(data.accountingUnit);
    const accountItemId = idOf(data.accountItemId);
    const closingAmount = amountText(data.closingAmount);
    if (!DATE_RE.test(periodStart) || !DATE_RE.test(periodEnd)) {
      throw invalid('결산 기간을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    if (!accountingUnit || accountingUnit.length > 50) {
      throw invalid('회계단위는 1~50자로 입력하세요.');
    }
    if (accountItemId === null) {
      throw invalid('계정과목을 선택하세요.');
    }
    if (closingAmount === null) {
      throw invalid('결산 금액은 소수 둘째 자리까지의 숫자여야 합니다.');
    }
    const memo = memoOf(data.memo);
    return transaction(async (db) => {
      const range = await db.query(
        'SELECT (CAST(:periodEnd AS date) >= CAST(:periodStart AS date)) AS "ok"',
        { periodStart, periodEnd },
      );
      if (!range[0].ok) {
        throw invalid('결산 기간 종료일은 시작일보다 빠를 수 없습니다.');
      }
      const item = await db.query(
        'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
        { accountItemId },
      );
      if (item.length === 0) {
        throw invalid('존재하지 않는 계정과목입니다.');
      }
      const closed = await db.query(
        `SELECT closing_entry_id FROM closing_entry
         WHERE period_start = CAST(:periodStart AS date)
           AND period_end = CAST(:periodEnd AS date)
           AND accounting_unit = :accountingUnit
           AND status = :closedStatus`,
        { periodStart, periodEnd, accountingUnit, closedStatus: CLOSED_STATUS },
      );
      if (closed.length > 0) {
        throw new ApiError(409, 'CLOSING_ENTRY_CLOSED', '해당 기간이 이미 마감되어 등록할 수 없습니다.');
      }
      const dup = await db.query(
        `SELECT closing_entry_id FROM closing_entry
         WHERE period_start = CAST(:periodStart AS date)
           AND period_end = CAST(:periodEnd AS date)
           AND accounting_unit = :accountingUnit
           AND account_item_id = CAST(:accountItemId AS bigint)`,
        { periodStart, periodEnd, accountingUnit, accountItemId },
      );
      if (dup.length > 0) {
        throw invalid('같은 기간·회계단위·계정과목의 결산자료가 이미 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO closing_entry
           (account_item_id, period_start, period_end, accounting_unit, closing_amount, memo, status, created_at, updated_at)
         VALUES
           (CAST(:accountItemId AS bigint), CAST(:periodStart AS date), CAST(:periodEnd AS date), :accountingUnit,
            CAST(:closingAmount AS numeric), :memo, :status, now(), now())
         RETURNING closing_entry_id AS "closingEntryId"`,
        {
          accountItemId,
          periodStart,
          periodEnd,
          accountingUnit,
          closingAmount,
          memo,
          status: INITIAL_STATUS,
        },
      );
      return { closingEntryId: Number(rows[0].closingEntryId) };
    });
  }

  @Put('/closing-entries/:closingEntryId')
  async updateClosingEntry(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['closingEntryId']);
    if (id === null) {
      throw new ApiError(404, 'CLOSING_ENTRY_NOT_FOUND', '결산자료를 찾을 수 없습니다.');
    }
    const data = checks.inputOf(req.body);
    const accountItemId = idOf(data.accountItemId);
    const closingAmount = amountText(data.closingAmount);
    if (accountItemId === null) {
      throw invalid('계정과목을 선택하세요.');
    }
    if (closingAmount === null) {
      throw invalid('결산 금액은 소수 둘째 자리까지의 숫자여야 합니다.');
    }
    const memo = memoOf(data.memo);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT status AS "status", period_start AS "periodStart", period_end AS "periodEnd",
                accounting_unit AS "accountingUnit"
         FROM closing_entry WHERE closing_entry_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CLOSING_ENTRY_NOT_FOUND', '결산자료를 찾을 수 없습니다.');
      }
      if (found[0].status === CLOSED_STATUS) {
        throw new ApiError(409, 'CLOSING_ENTRY_CLOSED', '마감된 결산자료입니다. 마감취소 후 수정하세요.');
      }
      const item = await db.query(
        'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
        { accountItemId },
      );
      if (item.length === 0) {
        throw invalid('존재하지 않는 계정과목입니다.');
      }
      const dup = await db.query(
        `SELECT closing_entry_id FROM closing_entry
         WHERE closing_entry_id <> CAST(:id AS bigint)
           AND period_start = CAST(:periodStart AS date)
           AND period_end = CAST(:periodEnd AS date)
           AND accounting_unit = :accountingUnit
           AND account_item_id = CAST(:accountItemId AS bigint)`,
        {
          id,
          periodStart: String(found[0].periodStart).slice(0, 10),
          periodEnd: String(found[0].periodEnd).slice(0, 10),
          accountingUnit: found[0].accountingUnit,
          accountItemId,
        },
      );
      if (dup.length > 0) {
        throw invalid('같은 기간·회계단위·계정과목의 결산자료가 이미 있습니다.');
      }
      await db.execute(
        `UPDATE closing_entry
         SET account_item_id = CAST(:accountItemId AS bigint),
             closing_amount = CAST(:closingAmount AS numeric),
             memo = :memo,
             updated_at = now()
         WHERE closing_entry_id = CAST(:id AS bigint)`,
        { id, accountItemId, closingAmount, memo },
      );
      return { closingEntryId: Number(id) };
    });
  }

  @Delete('/closing-entries/:closingEntryId')
  async deleteClosingEntry(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['closingEntryId']);
    if (id === null) {
      throw new ApiError(404, 'CLOSING_ENTRY_NOT_FOUND', '결산자료를 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status AS "status" FROM closing_entry WHERE closing_entry_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CLOSING_ENTRY_NOT_FOUND', '결산자료를 찾을 수 없습니다.');
      }
      if (found[0].status === CLOSED_STATUS) {
        throw new ApiError(409, 'CLOSING_ENTRY_CLOSED', '마감된 결산자료는 삭제할 수 없습니다.');
      }
      await db.execute(
        'DELETE FROM closing_entry WHERE closing_entry_id = CAST(:id AS bigint)',
        { id },
      );
      return {};
    });
  }
}

