import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  NumberInput,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;

type Panel =
  | { kind: 'create' }
  | { kind: 'detail'; row: Row }
  | { kind: 'edit'; row: Row }
  | { kind: 'delete'; row: Row };

interface Applied {
  periodStart: string;
  periodEnd: string;
  accountingUnit: string;
}

const EMPTY: Applied = { periodStart: '', periodEnd: '', accountingUnit: '' };

function EntryForm({
  role,
  row,
  onDone,
}: {
  role: string;
  row?: Row;
  onDone: (text: string) => void;
}) {
  const editing = row !== undefined;
  const [periodStart, setPeriodStart] = useState('');
  const [periodEnd, setPeriodEnd] = useState('');
  const [accountingUnit, setAccountingUnit] = useState('');
  const [accountItemId, setAccountItemId] = useState<unknown>(row ? row.accountItemId : '');
  const [closingAmount, setClosingAmount] = useState<unknown>(row ? row.closingAmount : '');
  const [memo, setMemo] = useState<unknown>(row && row.memo ? row.memo : '');

  async function submit() {
    if (!accountItemId) {
      throw new Error('계정과목을 선택하세요.');
    }
    if (closingAmount === '' || closingAmount === null || closingAmount === undefined) {
      throw new Error('결산 금액을 입력하세요.');
    }
    if (editing) {
      await call('PUT', '/closing-entries/' + String(row.closingEntryId), role, {
        accountItemId,
        closingAmount,
        memo: memo === '' ? undefined : memo,
      });
      onDone('결산자료를 수정했습니다.');
      return;
    }
    if (!periodStart || !periodEnd) {
      throw new Error('결산 기간을 입력하세요.');
    }
    if (!accountingUnit.trim()) {
      throw new Error('회계단위를 입력하세요.');
    }
    await call('POST', '/closing-entries', role, {
      periodStart,
      periodEnd,
      accountingUnit: accountingUnit.trim(),
      accountItemId,
      closingAmount,
      memo: memo === '' ? undefined : memo,
    });
    onDone('결산자료를 등록했습니다.');
  }

  return (
    <Form onSubmit={submit} submit={editing ? '수정' : '등록'}>
      {!editing && (
        <Field label='결산 기간 시작일' required>
          <DateInput value={periodStart} onChange={setPeriodStart} />
        </Field>
      )}
      {!editing && (
        <Field label='결산 기간 종료일' required>
          <DateInput value={periodEnd} onChange={setPeriodEnd} />
        </Field>
      )}
      {!editing && (
        <Field label='회계단위' required>
          <TextInput value={accountingUnit} onChange={setAccountingUnit} />
        </Field>
      )}
      <Field label='계정과목' required>
        <LookupSelect
          table='account_item'
          role={role}
          value={accountItemId}
          onChange={setAccountItemId}
          placeholder='계정과목 선택'
        />
      </Field>
      <Field label='결산 금액' required>
        <NumberInput value={closingAmount} onChange={setClosingAmount} />
      </Field>
      <Field label='적요' wide>
        <TextInput value={memo} onChange={setMemo} multiline />
      </Field>
    </Form>
  );
}

export default function FnSfr01001Page({ role, notify }: PageProps) {
  const [periodStart, setPeriodStart] = useState('');
  const [periodEnd, setPeriodEnd] = useState('');
  const [accountingUnit, setAccountingUnit] = useState('');
  const [applied, setApplied] = useState<Applied>(EMPTY);
  const [filterError, setFilterError] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [panel, setPanel] = useState<Panel | null>(null);

  const list = useData<Page>(async () => {
    if (!applied.periodStart || !applied.periodEnd) {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/closing-entries', role, undefined, {
      periodStart: applied.periodStart,
      periodEnd: applied.periodEnd,
      accountingUnit: applied.accountingUnit,
      page: pageNo,
      size: SIZE,
    });
  }, [applied, pageNo, role]);

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const sum = rows.reduce((acc, r) => acc + (Number(r.closingAmount) || 0), 0);
  const pending = rows.filter((r) => r.status === '신청').length;

  function search() {
    if (!periodStart || !periodEnd) {
      setFilterError('결산 기간 시작일과 종료일을 입력하세요.');
      return;
    }
    setFilterError('');
    setPageNo(0);
    setApplied({ periodStart, periodEnd, accountingUnit: accountingUnit.trim() });
  }

  function reset() {
    setPeriodStart('');
    setPeriodEnd('');
    setAccountingUnit('');
    setFilterError('');
    setPageNo(0);
    setApplied(EMPTY);
  }

  function done(text: string) {
    setPanel(null);
    notify(text);
    list.reload();
  }

  async function remove(row: Row) {
    await call('DELETE', '/closing-entries/' + String(row.closingEntryId), role);
    done('결산자료를 삭제했습니다.');
  }

  const columns: Column[] = [
    { key: 'closingEntryId', label: '결산자료 ID' },
    {
      key: 'accountItemId',
      label: '계정과목',
      render: (r) => <RefName table='account_item' role={role} value={r.accountItemId} />,
    },
    { key: 'periodStart', label: '결산 기간 시작일', render: (r) => <DateText value={r.periodStart} /> },
    { key: 'periodEnd', label: '결산 기간 종료일', render: (r) => <DateText value={r.periodEnd} /> },
    { key: 'accountingUnit', label: '회계단위' },
    { key: 'closingAmount', label: '결산 금액', render: (r) => <Num value={r.closingAmount} /> },
    { key: 'memo', label: '적요' },
    { key: 'status', label: '확정·마감 상태', render: (r) => <Badge value={r.status} /> },
  ];

  const selected = panel && panel.kind !== 'create' ? panel.row : undefined;
  const editable = selected !== undefined && selected.status !== '마감';

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>조회 건수</h2>
        <Tiles items={[['결산자료', <Num value={total} />]]} />
      </section>
      <section className='box span-4'>
        <h2>결산 금액 합계</h2>
        <Tiles items={[['현재 쪽', <Num value={sum} />]]} />
      </section>
      <section className='box span-4'>
        <h2>처리 대기</h2>
        <Tiles items={[['신청 상태', <Num value={pending} />]]} />
      </section>
      <section className='box span-12'>
        <h2>결산자료</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='결산 기간 시작일' required>
            <DateInput value={periodStart} onChange={setPeriodStart} />
          </Field>
          <Field label='결산 기간 종료일' required>
            <DateInput value={periodEnd} onChange={setPeriodEnd} />
          </Field>
          <Field label='회계단위'>
            <TextInput value={accountingUnit} onChange={setAccountingUnit} />
          </Field>
        </Filters>
        {filterError && <ErrorText text={filterError} />}
        {list.error && <ErrorText text={list.error} />}
        <Band total={total}>
          <button type='button' onClick={() => setPanel({ kind: 'create' })}>
            결산자료 등록
          </button>
        </Band>
        <DataTable
          columns={columns}
          rows={rows}
          onRowClick={(row) => setPanel({ kind: 'detail', row })}
          empty='결산 기간을 조회하세요.'
        />
        <Pager page={pageNo} size={SIZE} total={total} onPage={setPageNo} />
      </section>
      {panel && panel.kind === 'create' && (
        <Drawer title='결산자료 등록' onClose={() => setPanel(null)}>
          <EntryForm role={role} onDone={done} />
        </Drawer>
      )}
      {panel && panel.kind === 'detail' && (
        <Drawer title='결산자료 상세' onClose={() => setPanel(null)}>
          <Pairs
            items={[
              ['결산자료 ID', String(panel.row.closingEntryId)],
              ['계정과목', <RefName table='account_item' role={role} value={panel.row.accountItemId} />],
              ['결산 기간 시작일', <DateText value={panel.row.periodStart} />],
              ['결산 기간 종료일', <DateText value={panel.row.periodEnd} />],
              ['회계단위', String(panel.row.accountingUnit ?? '')],
              ['결산 금액', <Num value={panel.row.closingAmount} />],
              ['적요', String(panel.row.memo ?? '')],
              ['확정·마감 상태', <Badge value={panel.row.status} />],
            ]}
          />
          {editable && (
            <div>
              <button type='button' onClick={() => setPanel({ kind: 'edit', row: panel.row })}>
                수정
              </button>
              <button type='button' onClick={() => setPanel({ kind: 'delete', row: panel.row })}>
                삭제
              </button>
            </div>
          )}
          {!editable && <p>마감된 결산자료는 마감취소 후에만 수정·삭제할 수 있습니다.</p>}
        </Drawer>
      )}
      {panel && panel.kind === 'edit' && (
        <Drawer title='결산자료 수정' onClose={() => setPanel(null)}>
          <EntryForm role={role} row={panel.row} onDone={done} />
        </Drawer>
      )}
      {panel && panel.kind === 'delete' && (
        <Drawer title='결산자료 삭제' onClose={() => setPanel(null)}>
          <Form
            onSubmit={() => remove(panel.row)}
            submit='삭제'
            danger
            note='삭제한 결산자료는 되돌릴 수 없습니다.'
          >
            <Pairs
              items={[
                ['계정과목', <RefName table='account_item' role={role} value={panel.row.accountItemId} />],
                ['결산 금액', <Num value={panel.row.closingAmount} />],
              ]}
            />
          </Form>
        </Drawer>
      )}
    </div>
  );
}
